import express, { Request, Response, Router } from 'express';
import path from 'path';
import fs from 'fs';
import { StaticFileService } from '../services/StaticFileService';
import { createLogger } from '../utils/logger';
import { injectPreviewBridge } from '../proxy-middleware/preview-bridge';
import { renderRivetPage } from '../utils/rivetPage';

const log = createLogger('StaticRoutes');

type StaticRoutesOptions = {
  isPreviewBridgeEnabled?: boolean;
  expectedPreviewParentOrigin?: string;
};


export const createStaticRoutes = (
  staticService: StaticFileService,
  _projectPath: string,
  options: StaticRoutesOptions = {},
): Router => {
  const router = Router();

  const basePath = staticService.getBasePath();
  const entryFileName = staticService.getEntryFileName();

  log.info(`Serving static files from: ${basePath}`);
  log.info(`Entry file: ${entryFileName}`);

  const sendEntry = (res: Response, entryPath: string) => {
    if (options.isPreviewBridgeEnabled) {
      res
        .type('html')
        .send(
          injectPreviewBridge(fs.readFileSync(entryPath, 'utf8'), {
            expectedParentOrigin: options.expectedPreviewParentOrigin,
          }),
        );
      return;
    }
    res.sendFile(entryFileName, { root: basePath });
  };

  const sendEmptyState = (res: Response) => {
    res
      .status(200)
      .type('html')
      .send(
        renderRivetPage({
          page: { kind: 'empty-project' },
          head: { title: 'Empty project' },
        }),
      );
  };

  router.get('/static', (_req: Request, res: Response) => {
    const entryPath = path.join(basePath, entryFileName);
    log.debug(`Serving entry point: ${entryPath}`);
    if (!fs.existsSync(entryPath)) {
      sendEmptyState(res);
      return;
    }
    sendEntry(res, entryPath);
  });

  router.get('/static/', (_req: Request, res: Response) => {
    const entryPath = path.join(basePath, entryFileName);
    log.debug(`Serving entry point: ${entryPath}`);
    if (!fs.existsSync(entryPath)) {
      sendEmptyState(res);
      return;
    }
    sendEntry(res, entryPath);
  });

  router.use('/static', express.static(basePath));

  return router;
};
